//! The canonical model digest (architecture A6): the stream both sides write for a model, so
//! the parity compares the Rust `Document` with the TS `FullDocument` exactly, through hashed
//! `uo-testkit` streams. The TS side is `js/canon.mjs` (a generic walker over the TS objects);
//! the Rust side is [`crate::js::JsValue::canon`] of every model type, generated by
//! [`crate::js_object!`] or written by hand for the stories and their aliased views.
//!
//! The item encoding (both sides; `bytes`/`digest_of`/`u32`/`f64`/`bool`/`tag` are the
//! `uo_testkit::Stream` items):
//!
//! | value | items |
//! |---|---|
//! | `undefined` (an own key with that value) | `tag U` |
//! | `null` | `tag z` |
//! | boolean | `tag b`, `bool` |
//! | number | `tag n`, `f64` (NaN canonical `0x7ff8…`, `-0` kept) |
//! | string | `tag s`, `bytes` of its UTF-16LE code units (lone surrogates included) |
//! | `Uint8Array` | `tag B`, `digest_of` |
//! | array | `tag [`, `u32` length, the items |
//! | plain object | `tag {`, `u32` key count, then per key in UTF-16 order: `bytes` (UTF-16LE key), the value |
//! | `Map` | `tag M`, `u32` size, then key, value per entry in iteration order |
//! | `Set` | `tag S`, `u32` size, then the values in iteration order |
//! | a relabelled id (process-global counters, G7) | `tag i`, `u32` (first appearance = 0, per id space) |
//! | a source text (`SourceStore` raw slices) | `tag h`, `digest_of` its UTF-8 bytes |
//!
//! Aliased TS views (a cell's `paragraphs`/`tables` and `blocks`, a header's `headers` and
//! `headerBlocks`, the notes' `footnotes` and `footnoteBlocks`, a textbox's `paras` and `blocks`)
//! are written once from the block view, with a synthetic key `@views` whose value says how the
//! other view relates to it (`"synced"` when it is the same objects, see `js/canon.mjs`).
//!
//! The **key-order facet** is a second, non-compared stream (G23, LQ20): for every object, in the
//! same walk order, `tag o`, `u32` count, then its keys in insertion order (`Object.keys`).

use std::cmp::Ordering;
use std::collections::HashMap;

use crate::model::MediaStore;
use crate::model::sources::SourcePart;

/// Where the canonical items go (the tests adapt `uo_testkit::Stream`).
pub trait CanonSink {
    fn tag(&mut self, c: u8);
    fn u32(&mut self, v: u32);
    fn f64(&mut self, v: f64);
    fn bool(&mut self, v: bool);
    fn bytes(&mut self, b: &[u8]);
    fn digest_of(&mut self, b: &[u8]);
}

/// Id spaces of the relabelled process-global counters (G7).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum IdSpace {
    /// `BlockSdt.key` / `StoryGroup.sdtKey` (`blockSdtKeys`, fulldoc.ts)
    BlockSdt,
    /// `WrapSeg.open` / `.close` (`wrapIds`, fulldoc.ts)
    Wrap,
}

/// Writes canonical items for a model (see the module comment).
pub struct CanonWriter<'a> {
    sink: &'a mut dyn CanonSink,
    order: Option<&'a mut dyn CanonSink>,
    media: Option<&'a MediaStore>,
    parts: &'a [SourcePart],
    relabel: HashMap<(IdSpace, Box<str>), u32>,
    next: HashMap<IdSpace, u32>,
}

/// UTF-16 code-unit order of two strings (JS `<` on strings, `Array.prototype.sort` default).
pub fn utf16_cmp(a: &str, b: &str) -> Ordering {
    if a.is_ascii() && b.is_ascii() {
        return a.cmp(b);
    }
    a.encode_utf16().cmp(b.encode_utf16())
}

fn utf16le(s: &str) -> Vec<u8> {
    s.encode_utf16().flat_map(u16::to_le_bytes).collect()
}

impl<'a> CanonWriter<'a> {
    pub fn new(sink: &'a mut dyn CanonSink) -> CanonWriter<'a> {
        CanonWriter { sink, order: None, media: None, parts: &[], relabel: HashMap::new(), next: HashMap::new() }
    }

    /// Also writes the key-order facet to `order`.
    #[must_use]
    pub fn with_order(mut self, order: &'a mut dyn CanonSink) -> CanonWriter<'a> {
        self.order = Some(order);
        self
    }

    /// The media bytes of the document (needed for `Uint8Array` fields).
    #[must_use]
    pub fn with_media(mut self, media: &'a MediaStore) -> CanonWriter<'a> {
        self.media = Some(media);
        self
    }

    pub fn media(&self) -> Option<&'a MediaStore> {
        self.media
    }

    /// The source texts of the document (needed for `SourceStore` spans).
    #[must_use]
    pub fn with_parts(mut self, parts: &'a [SourcePart]) -> CanonWriter<'a> {
        self.parts = parts;
        self
    }

    pub fn parts(&self) -> &'a [SourcePart] {
        self.parts
    }

    /// A `Set`: `tag S`, `u32` size, then the values.
    pub fn set(&mut self, len: usize) {
        self.sink.tag(b'S');
        self.sink.u32(u32::try_from(len).unwrap_or(u32::MAX));
    }

    pub fn undefined(&mut self) {
        self.sink.tag(b'U');
    }

    pub fn null(&mut self) {
        self.sink.tag(b'z');
    }

    pub fn bool(&mut self, v: bool) {
        self.sink.tag(b'b');
        self.sink.bool(v);
    }

    pub fn num(&mut self, x: f64) {
        self.sink.tag(b'n');
        self.sink.f64(if x.is_nan() { f64::from_bits(0x7ff8_0000_0000_0000) } else { x });
    }

    pub fn str(&mut self, s: &str) {
        self.sink.tag(b's');
        self.sink.bytes(&utf16le(s));
    }

    pub fn str16(&mut self, units: &[u16]) {
        self.sink.tag(b's');
        let b: Vec<u8> = units.iter().flat_map(|u| u.to_le_bytes()).collect();
        self.sink.bytes(&b);
    }

    pub fn bytes(&mut self, b: &[u8]) {
        self.sink.tag(b'B');
        self.sink.digest_of(b);
    }

    pub fn array(&mut self, len: usize) {
        self.sink.tag(b'[');
        self.sink.u32(u32::try_from(len).unwrap_or(u32::MAX));
    }

    pub fn object(&mut self, keys: usize) {
        self.sink.tag(b'{');
        self.sink.u32(u32::try_from(keys).unwrap_or(u32::MAX));
    }

    /// The next key of an object (after [`CanonWriter::object`]).
    pub fn key(&mut self, k: &str) {
        self.sink.bytes(&utf16le(k));
    }

    pub fn map(&mut self, len: usize) {
        self.sink.tag(b'M');
        self.sink.u32(u32::try_from(len).unwrap_or(u32::MAX));
    }

    /// A process-global id, relabelled by first appearance in its space.
    pub fn id(&mut self, space: IdSpace, raw: &str) {
        let key = (space, Box::from(raw));
        let v = match self.relabel.get(&key) {
            Some(&v) => v,
            None => {
                let n = self.next.entry(space).or_insert(0);
                let v = *n;
                *n += 1;
                self.relabel.insert(key, v);
                v
            }
        };
        self.sink.tag(b'i');
        self.sink.u32(v);
    }

    /// A source text (raw XML slice) by content.
    pub fn text_digest(&mut self, s: &str) {
        self.sink.tag(b'h');
        self.sink.digest_of(s.as_bytes());
    }

    /// Writes the key-order facet entry of one object, if the facet is on: `keys` calls `f` with
    /// each key in insertion order.
    pub fn order_facet(&mut self, keys: impl FnOnce(&mut dyn FnMut(&str))) {
        if let Some(o) = self.order.as_deref_mut() {
            let mut list: Vec<Box<str>> = Vec::new();
            keys(&mut |k| list.push(k.into()));
            o.tag(b'o');
            o.u32(u32::try_from(list.len()).unwrap_or(u32::MAX));
            for k in &list {
                o.bytes(&utf16le(k));
            }
        }
    }
}

/// Writes an object whose entries are given explicitly (hand-written model types): sorts the
/// keys, writes the order facet in the given (insertion) order.
pub fn canon_entries(w: &mut CanonWriter<'_>, entries: &mut [EntryRef<'_>]) {
    w.order_facet(|f| {
        for (k, _) in entries.iter() {
            f(k);
        }
    });
    entries.sort_by(|a, b| utf16_cmp(a.0, b.0));
    w.object(entries.len());
    for (k, v) in entries.iter() {
        w.key(k);
        v(w);
    }
}

/// A writer of one value.
pub type ValueFn<'f> = dyn Fn(&mut CanonWriter<'_>) + 'f;

/// One entry of a hand-written object: its key and a writer of its value.
pub type Entry<'e> = (&'e str, Box<ValueFn<'e>>);

/// A borrowed [`Entry`].
pub type EntryRef<'e> = (&'e str, &'e ValueFn<'e>);

/// [`canon_entries`] over owned entries (in insertion order).
pub fn canon_boxed(w: &mut CanonWriter<'_>, entries: Vec<Entry<'_>>) {
    let mut refs: Vec<EntryRef<'_>> = entries.iter().map(|(k, f)| (*k, &**f)).collect();
    canon_entries(w, &mut refs);
}

/// A sink that keeps the raw bytes (unit tests: two models give the same stream).
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct BytesSink(pub Vec<u8>);

impl CanonSink for BytesSink {
    fn tag(&mut self, c: u8) {
        self.0.push(c);
    }
    fn u32(&mut self, v: u32) {
        self.0.extend_from_slice(&v.to_le_bytes());
    }
    fn f64(&mut self, v: f64) {
        self.0.extend_from_slice(&v.to_bits().to_le_bytes());
    }
    fn bool(&mut self, v: bool) {
        self.0.push(u8::from(v));
    }
    fn bytes(&mut self, b: &[u8]) {
        self.0.extend_from_slice(&(b.len() as u64).to_le_bytes());
        self.0.extend_from_slice(b);
    }
    fn digest_of(&mut self, b: &[u8]) {
        // not SHA-256 (no dependency here): length + the bytes, enough to compare two streams
        self.bytes(b);
    }
}
